   682	func removeReviewGoBuildLeftovers(root *os.Root) error {
   683		// The top level is read in bounded batches and each go-build directory
   684		// is removed as it is read, so nothing accumulates; only the other
   685		// entries, which the runtime inventory will judge, count against its
   686		// bound (review rounds 5 and 6, N6 and N10).
